To add point markers at each quarter, we can change the mark type to "line" and "point" using a layer or a mark property with "type" as "line" and add a second layer with "type" as "point", or more simply, use a single layer with a "point" mark and set "point" property in the "line" mark configuration, but the most straightforward way is to layer a line and a point mark. However, an easier way is to just add a "point" property to the line mark.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://gicentre.github.io/data/tests/timeTest.tsv"
  },
  "encoding": {
    "x": {
      "field": "date",
      "timeUnit": "quarter",
      "type": "temporal"
    },
    "y": {
      "aggregate": "mean",
      "field": "temperature",
      "type": "quantitative"
    }
  },
  "layer": [
    {
      "mark": {
        "type": "line",
        "color": "#FF9900",
        "strokeWidth": 2
      }
    },
    {
      "mark": {
        "type": "point",
        "color": "#FF9900",
        "size": 50
      }
    }
  ],
  "width": 800
}
```

